// Definition for a binary tree node.
class Node {
    int data;
    Node left;
    Node right;
}

public boolean checkBST(Node root) {
    if (root == null) return true;
    if (root.left != null && subtreeMax(root.left) >= root.data) return false;   // strict
    if (root.right != null && subtreeMin(root.right) <= root.data) return false; // strict
    return checkBST(root.left) && checkBST(root.right);
}

private int subtreeMax(Node node) {
    int best = node.data;
    if (node.left != null) best = Math.max(best, subtreeMax(node.left));
    if (node.right != null) best = Math.max(best, subtreeMax(node.right));
    return best;
}

private int subtreeMin(Node node) {
    int best = node.data;
    if (node.left != null) best = Math.min(best, subtreeMin(node.left));
    if (node.right != null) best = Math.min(best, subtreeMin(node.right));
    return best;
}

