# Definition for a binary tree node.
class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def check_bst(root: Node) -> bool:
    if root is None:
        return True
    if root.left is not None and subtree_max(root.left) >= root.data:   # strict
        return False
    if root.right is not None and subtree_min(root.right) <= root.data: # strict
        return False
    return check_bst(root.left) and check_bst(root.right)

def subtree_max(node: Node) -> int:
    best = node.data
    if node.left:
        best = max(best, subtree_max(node.left))
    if node.right:
        best = max(best, subtree_max(node.right))
    return best

def subtree_min(node: Node) -> int:
    best = node.data
    if node.left:
        best = min(best, subtree_min(node.left))
    if node.right:
        best = min(best, subtree_min(node.right))
    return best

