private boolean isBST(Node node, long low, long high) {
    if (node == null) return true;                 // empty subtree is valid
    if (node.data <= low || node.data >= high) {   // strict: must be inside (low, high)
        return false;
    }
    return isBST(node.left, low, node.data)        // left: high tightens to node
        && isBST(node.right, node.data, high);     // right: low tightens to node
}

